  "account.genTitle": "Kód generálása Garminhoz",
  "account.genHelp": "Csak Garmin: ha nem szeretnéd leolvasni a kódot az óráról, generálj egyet itt, és írd be a Garmin Connect appban a „Pumpfoil” → Beállítások alatt. Wear OS, Apple Watch és Amazfit esetén ez az út nem létezik — ott az óra mutatja a kódot, és te fent írod be.",
