  "account.browseAllHint": "Be (alapértelmezés): minden oldal minden állapotban elérhető. Ki: csak az itt állapotonként hozzárendelt képernyők — rendezettebb, de kint a vízen nem minden érhető el.",
  "account.noLayoutsOfKind": "Még nincs ilyen típusú saját képernyő.",
