  "sd.tapDeleteConfirm": "Törlöd mind a(z) {n} mentett menetet ehhez a körhöz?",
  "sd.tapHelp": "<b>Pumpák jelölése</b> — jelöld a valódi pumpákat az automatikus felismerő tanításához. Kell hozzá egy <b>videó</b> az edzésről.<br><br><b>Így csináld:</b><br>1. Válaszd ki fent a <b>kört</b>.<br>2. <b>Szinkron:</b> keress egy jól látható <b>GPS-törést</b>, ami az útvonalon és a videón is látszik (pl. egy éles kanyar). Kattints az <b>Indítás (3-2-1)</b> gombra, és indítsd a videódat úgy, hogy annál a törésnél együtt fussanak.<br>3. Nyomd meg a <b>szóközt</b> <b>minden</b> pumpánál (vagy <b>PUMP</b>). Aztán <b>Felvétel mentése</b>.<br>4. Jelöld ugyanazt a kört <b>3–4×</b>, aztán <b>Összehasonlítás</b>.<br><br><b>Ami számít:</b><br>• A szinkronnak <b>nem</b> kell pontosnak lennie — ±½ pumpaütem (~0,3–0,5 s) rendben van; 1 s határeset, több másodperc túl sok (a pumpák periodikusak, különben kétértelmű lesz). Minden felvételnél <b>ugyanazt a törést</b> használd.<br>• Az abszolút pontosságnál fontosabb az <b>egyenletes</b> koppintás arra, amit látsz — több felvétel automatikusan kiátlagolja a reakcióidődet.<br>• A pontozás <b>az első koppintásnál</b> kezdődik; az előtte lévő nekifutás nem számít. A véletlen koppintásokat (pl. a csobbanás, amikor beesel) a felvételek <b>többsége</b> kiszűri.<br>• <b>Csak pumpákat</b> jelölj — a siklási szakaszok automatikusan adódnak (minden a pumpák között). Mást ne jelölj.",
