  "adm.usport.hint": "Azoknak a felhasználóknak, akik soha nem válaszolnak a besorolási kérésre. Három külön művelet: a profil alapértéke csak a JÖVŐBELI edzésekre hat, a megoldás csak a meglévő, nyitott kérésű edzésekre, az „Összes edzés beállítása” pedig minden meglévő edzésre, amit még senki nem sorolt be — kérés nélkül is. A „pumpfoil” választása az érintett edzéseket új jelentések ellen is zárolja.",
