  "adm.abs.erklaerung": "Az órás alkalmazások jelentései modellenként, minden órára és felhasználóra. Futam = egy alkalmazásfutás nem zárult le rendben (akkor is, ha az egész óra újraindul vagy lemerül az akku); Tárhely = az alkalmazás puffere megtelt; Layout = összeomlás dinamikus elrendezéssel. Napló 2026. nov. 21. óta, „eddig” = számlálók a bevezetés óta, időbélyeg nélkül.",
