  "settings.sports.title": "Mely sportágakat importáljuk?",
  "settings.sports.hint": "Csak azok a módok, amelyeket a fiókod eddig ténylegesen küldött. Egy újat automatikusan importálunk, amíg ki nem veszed a pipát. A jövőbeli importokra vonatkozik.",
