  "settings.sports.countsDefault": "alapértelmezett sportág",
  "settings.coros.help2": "Az órán rögzíts GPS-es kültéri tevékenységet. Méréseink szerint a „Flatwater” adja a legjobb adatokat (másodpercenként egy pont, sebesség és pulzus hiánytalanul). A beltéri/GPS nélküli kimarad.",
  "settings.coros.help3": "A pumpaelemzés korlátozott: a COROS-export nem tartalmaz nyers gyorsulásmérő-adatfolyamot — a GPS-t + pulzust elemezzük.",
  "settings.coros.help4": "Bármikor leválaszthatod (visszavonja a hozzáférést és leállítja az importot).",
  "settings.garmin.hint": "Kapcsold össze a Garmin Connect-fiókodat. A Garmineden – bármely profillal – rögzített GPS-es tevékenységek ezután automatikusan ide érkeznek edzésként.",
