  "settings.garmin.unlink": "Leválasztás",
  "settings.garmin.noExport": "A tevékenységek megosztása a Pumpfoillal ki van kapcsolva a Garmin Connectben – semmi nem érkezik, amíg vissza nem kapcsolod.",
  "settings.garmin.help1": "Csak az összekapcsolás pillanatától származó tevékenységek; a régebbieket nem kérjük le.",
  "settings.garmin.help2": "Minden profil automatikusan beérkezik. Amint megérkezik vele az első tevékenység, megjelenik a lenti listában – ott vedd ki a pipát abból, amit itt nem szeretnél (pl. futás).",
  "settings.garmin.help3": "Az órán a Pumpfoil-alkalmazásunkkal készült felvételek továbbra is közvetlenül érkeznek, és nem jönnek létre kétszer. A Garmin a teljes fájljukat is elküldi, amit az edzésedhez csatolunk – ha a közvetlen feltöltésnél valami elveszne, az még megvan. Pumpákat csak az alkalmazásunkkal készült felvételeknél számolunk.",
  "settings.garmin.help4": "Bármikor leválaszthatod, itt vagy a Garmin Connectben.",
  "settings.suunto.title": "Suunto-import",
