  "settings.suunto.activity": "A Suuntónak nincs pumpfoil módja: egyszerűen rögzíts Stand-up paddling vagy Surfing módban. A pumpfoilozást automatikusan felismerjük, bármelyik módot is használod.",
  "settings.suunto.broken": "⚠ A Suunto-összekapcsolás jelenleg nem működik: a bejelentkezés a Suuntónál sikerül (a Suunto még megerősítő e-mailt is küld), de ezután a Suunto megtagadja az alkalmazásunk hozzáférését a fiókodhoz. Ez nem a te hibád, és semmi köze a jelszavadhoz — a Suuntóval együtt dolgozunk a megoldáson. Addig a Suunto-tevékenységeket fájlként importálhatod.",
