  "cls.confirmFlag": "Szerinted ez nem pumpfoil edzés? A tulajdonos barátságos kérést kap, hogy sorolja be helyesen – például wingfoilként vagy foildrive-ként. Névtelen maradsz, és senkit nem vádolunk semmivel: csak arról van szó, hogy a rekordok összehasonlíthatók maradjanak.",
  "cls.thanks": "Köszönjük! Megkérjük a tulajdonost, hogy sorolja be ezt az edzést.",
  "cls.fileAsk": "Az órád ezt a felvételt „{sport}” néven mentette, ezért nem tudjuk, pumpfoil volt-e. Besorolnád? Addig egyik statisztikában sem jelenik meg. Ha mégis pumpfoil volt, egyszerűen válaszd a „Pumpfoil” lehetőséget.",
  "cls.ownerAsk": "Egy másik foilos szerint ez az edzés nem pumpfoil. Besorolnád? Addig egyik statisztikában sem jelenik meg. Ha tényleg pumpfoil volt, szólj, és megnézzük.",
