  "cls.autoAsk": "Ez az edzés szerintünk nem pumpfoilnak tűnik – ezért egyelőre egyik statisztikába sem számít bele. Besorolnád? Ha tényleg pumpfoil volt, egyszerűen válaszd a „Pumpfoil” lehetőséget.",
