  "team.event.teilen": "Megosztás:",
  "team.event.regelnTitel": "Eseményszabályok",
  "team.event.disclaimer": "Az eseményeket maguk a csapatok szervezik. A pumpfoil.org nincs befolyással az eseményekre és az azokban tett pénzügyi vagy egyéb ígéretekre, és nem vállal értük felelősséget. A bírósági út kizárt. A kifizetéseket és minden egyéb megállapodást a szervezők és a résztvevők egymás között, a pumpfoil.org-tól függetlenül rendezik. A pumpfoil.org azért sem vállal felelősséget, hogy a mért értékek és adatok helyesek-e, vagy manipulálták-e őket. Az jelenik meg, amit a GitHubon lévő nyilvános forráskód a feltöltött adatokból kiszámol; további ígéret nincs.",
