  "team.event.status.beendet": "befejeződött",
  "team.event.auswertungHinweis": "Vége. Az ablakba eső edzések még {bis}-ig feltölthetők, utána az eredmény végleges.",
  "team.vorlage.wochenende_pumps": "Legtöbb pump a hétvégén",
