  "perf.saison.platz": "Hely",
  "perf.saison.mitmachen": "Minden vízen töltött nap (legalább egy felismert futam): +{n} pont",
  "perf.saison.kategorien": "Kategóriák: {kats}",
  "perf.saison.regeln": "Helyezési pontok azokon a napokon járnak, amikor a kategóriában legalább {n} foilos van. Holtversenynél azonos pont jár. Naponta legfeljebb {max} pont. A szezon január 1-jétől {jahr}. december 31-ig tart; a félretett, javított vagy törölt futamok kiesnek.",
  "team.vorlage.gpskunst": "GPS-művészet: ki rajzolja a legmenőbb képet a vízre?",
  "kunst.einstellungHinweis": "Ranglisták helyett: a foilosok fordulónként egy képet adnak be egyik edzésükből, majd a közösség névtelenül, szívecskékkel szavaz. Közben már fut a következő forduló.",
  "kunst.rundenTage": "Új forduló ennyi naponta",
  "kunst.abstimmenTage": "Szavazás utána (napok)",
  "kunst.regeln": "Minden fordulóban csak a saját, az adott forduló alatt rögzített edzéseid számítanak, bármilyen sport, szárazföldön is.\nCsak a foilon töltött idő rajzolódik ki. Több futam is kombinálható, de csak ugyanannak az edzésnek egymást követő futamai.\nMindenki fordulónként egy képet ad be, és a forduló végéig módosíthatja vagy visszavonhatja.\nA többiek képei csak a szavazás kezdetekor válnak láthatóvá.\nA forduló után szavazás következik: névtelen, csak a vonal látszik, mindenkinek 3 szíve van, a saját képére egy sem.\nHogy ki hány szívet kapott, csak a szavazás után derül ki – akkor névvel és spottal (hacsak nincs elrejtve).\nA humor szívesen látott. Csak a valóban tiltott tartalmat távolítjuk el; a foilos látja az okát.",
