  "brett.erkl.titel": "Mi a deszka helyzete?",
  "brett.erkl.was": "Ha a telefonod az edzés alatt a deszkára van rögzítve, a giroszkópja méri, hogyan bólint és dől a deszka – közvetlenül a forrásnál, nem a csuklódon.",
  "brett.erkl.wie": "Így működik: tedd a telefonodat vízálló tokba, rögzítsd laposan a deszka tetejére, és indítsd el a felvételt a telefonon a Pumpfoil appban. Az órád közben szintén rögzíthet. Az elemzés általában magától észreveszi, hogy a telefon a deszkán volt.",
  "brett.erkl.bringt": "Mit nyersz vele: látod, mennyire stabil a deszkád pumpálás közben, mennyit bólint és dől pumponként, és hogy ez eltér-e foilok, fordulók és egyenesek között. Minden ilyen felvétel az órás pumpfelismerés javításához is hozzájárul.",
  "brett.erkl.daten": "A kapott adatok: bólintás és dőlés pumponként, dőlésszög, ütem, fordulók kontra egyenesek és a hullámzás (a fel-le mozgás, ha a pumpritmus megbízhatóan felismerhető) – futamonként, itt pedig az összes futam áttekintéseként és foilonként.",
  "brett.erkl.mehr": "Tudj meg többet",
