  "team.event.meinTeamHinweis": "Több csapatban vagy, és ezen az eseményen egyiküknél számítasz. Az esemény vége előtt 6 óráig módosíthatod.",
  "team.event.zaehltNicht": "Globális eseményeken nem számít (a csapat nincs jóváhagyva vagy a ranglisták nem nyilvánosak)",
  "team.event.meinTeamFest": "Kevesebb mint 6 óra van hátra – ez a választás végleges.",
  "team.feed30": "A csapattagok edzései az elmúlt 30 napból.",
  "period.yesterday": "Tegnap",
  "why.title": "Miért a pumpfoil.org?",
  "why.intro": "Futamokat és pumpokat mások is tudnak számolni. A pumpfoil.org többet tud:",
  "why.k1t": "Közösség, nem csak statisztika",
  "why.k1": "Ranglisták spot, időablak és foilméret szerint, csapatok saját ranglistákkal és eseményekkel, spotoldalak leírásokkal, hőtérképekkel és útvonalakkal azoktól, akik ott foiloznak, barátok és hogy ki hol pumpál éppen, chat, videók és megosztható óraelrendezések. Nem csak magadnak pumpálsz – látod, mi történik a spotodon és szerte a világon.",
  "why.k2t": "Olyan építi, aki maga is foilozik",
  "why.k2": "Jan 2026 júniusában kezdte, mert az, amit szeretett volna, nem létezett – és azóta szinte minden nap fejleszti.",
  "why.k3t": "A közösségnek beleszólása van",
  "why.k3": "A chatből és a visszajelzés gombról érkező ötletek gyakran napokon belül megjelennek az oldalon; mindenki, aki segít, kis támogatói jelvényt kap. Nem egy ügyfélszolgálatnak írsz, hanem közvetlenül annak, aki fejleszti.",
  "why.k4t": "Szabad szoftver",
  "why.k4": "A teljes kód nyílt a GitHubon (AGPL). Bárki ellenőrizheti, mi történik az adataival, segíthet a fejlesztésben vagy továbbviheti – a projekt nem függ egy cégtől, amely holnap bezárhatná vagy eladhatná.",
  "why.k5t": "Az adataid a tieid",
  "why.k5": "Nincs követés, nincsenek sütik, nincsenek hirdetések, nincs adateladás. Minden letölthető GPX, FIT vagy CSV formátumban, és a fiókod mindenestül egy gombnyomással eltűnik.",
  "why.k6t": "Átláthatóság",
  "why.k6": "Nyíltan megmondjuk, mi működik és mi (még) nem: mennyire pontos valójában a pump- és siklásfelismerés, és min alapul, melyik óra mire képes, melyik áruházi verziót utasították el és miért, mit találtak a biztonsági átvizsgálásaink. A változásnapló minden nap megmutatja, mi az újdonság, és hol tart az elemzés sportáganként – marketingígéretek nélkül, csak a valós állapot.",
  "why.k7t": "Minél többen csatlakoznak, annál jobb mindenkinek",
  "why.k7": "Minden edzés, minden elemzés értékelése, minden deszkára rögzített telefonnal készült felvétel pontosabbá teszi a felismerést – és mindenki profitál belőle, aki foilozik. Minden elemzés nyitott a közösség minden tagja számára, beleértve a foilonkénti és óránkénti összesített statisztikákat is: melyik foil meddig repül, melyik óra milyen jól rögzít? Mindenki a saját futamaival járul hozzá, és minden foilos élénkebbé teszi a ranglistákat, spotokat és útvonalakat.",
  "why.k8t": "Minden órára, nem egy márkára",
  "why.k8": "Garmin, Apple Watch, Wear OS, Amazfit, továbbá Polar, Suunto, COROS és a telefonod – nem kell egy bizonyos órát venned ahhoz, hogy csatlakozz. Saját Huawei- és Suunto-appjaink jelenleg áruházi ellenőrzés alatt állnak, és a lehető leghamarabb érkeznek.",
  "why.k9t": "Ingyenes, 18 nyelven",
  "why.k9": "A svájci és az osztrák német is köztük van.",
  "why.outro": "Próbáld ki, és mondd el, mi hiányzik – akár már jövő héten láthatod. Have fun, keep pumping!",
  "nav.why": "Miért a pumpfoil.org?",
